import type { Exercise } from "@/types";

/**
 * PAQUETE MEGA-8 · FORJA · Metáforas (reemplazo del banco antiguo).
 * ----------------------------------------------------------------
 * 520 imágenes ÚNICAS: cada ejercicio introduce una figura distinta
 * (nada se repite). Se carga bajo demanda (dynamic import).
 *
 * mk(): fábrica compacta — deriva dificultad (1-80·A1, 81-190·A2,
 * 191-310·B1, 311-420·B2, 421-520·C1/C2), rota answerIndex y alterna
 * la consigna para que el banco respire.
 */

const PROMPTS = [
  "Completa la metáfora con la imagen adecuada.",
  "Elige la imagen que enciende la figura.",
  "¿Qué imagen cierra la metáfora?",
  "Termina la figura con la palabra exacta.",
  "Escoge la imagen que hace brillar la frase.",
] as const;

function mk(
  n: number,
  stem: string,
  correct: string,
  w1: string,
  w2: string,
  explanation: string,
): Exercise {
  const difficulty = (n <= 80 ? 1 : n <= 190 ? 2 : n <= 310 ? 3 : n <= 420 ? 4 : 5) as Exercise["difficulty"];
  const cefr: Exercise["cefr"] =
    difficulty === 5 ? (n % 4 === 0 ? "C2" : "C1") : (["A1", "A2", "B1", "B2"] as const)[difficulty - 1];
  const slot = n % 3;
  const options =
    slot === 0 ? [correct, w1, w2] : slot === 1 ? [w1, correct, w2] : [w1, w2, correct];
  const answerIndex = slot === 0 ? 0 : slot === 1 ? 1 : 2;
  return {
    id: `metam8-${String(n).padStart(4, "0")}`,
    type: "metaforas",
    skill: "expresion",
    difficulty,
    cefr,
    stem,
    options,
    answerIndex,
    prompt: PROMPTS[n % 5],
    explanation,
    tags: ["retórica"],
  };
}

